import { and, eq, inArray, isNull, notInArray } from \"drizzle-orm\";
import { MAX_OPEN_MILESTONES_PER_PROJECT } from \"@/config/constants\";
import { emit } from \"@/lib/event-bus\";
import { newId } from \"@/lib/id\";
import { MilestoneStateError } from \"@/lib/milestones\";
import { assertCan } from \"@/lib/permissions\";
import { assertNotArchived } from \"@/lib/soft-delete\";
import { assertOrgScope } from \"@/lib/tenant\";
import { getDb, issues, milestones } from \"@/server/db\";
import * as projectRepo from \"@/server/repositories/project-repository\";
import { toIsoTimestamp } from \"@/types/common\";
import { actorEnvelope, projectResource, requireFound } from \"./_support\";
import type { CloseMilestoneInput, CreateMilestoneInput, UpdateMilestoneInput } from \"@/schemas/milestone\";
import type { IssueId, MilestoneId, OrgId, ProjectId } from \"@/types/common\";
import type { Actor } from \"@/types/member\";
import type { Milestone, MilestoneWithProgress } from \"@/types/milestone\";
import type { MilestoneRow } from \"@/server/db\";

function mapMilestone(row: MilestoneRow): Milestone {
  return { id: row.id as MilestoneId, orgId: row.orgId as OrgId, projectId: row.projectId as ProjectId,
    name: row.name, targetDate: row.targetDate as Milestone[\"targetDate\"], closedAt: row.closedAt as Milestone[\"closedAt\"],
    createdAt: row.createdAt as Milestone[\"createdAt\"], updatedAt: row.updatedAt as Milestone[\"updatedAt\"] };
}

function findMilestone(orgId: OrgId, id: MilestoneId): Milestone {
  return mapMilestone(requireFound(getDb().select().from(milestones).where(and(eq(milestones.orgId, orgId), eq(milestones.id, id))).get(), \"Milestone\", id));
}

export function requireOpenProjectMilestone(orgId: OrgId, projectId: ProjectId, id: MilestoneId): Milestone {
  const milestone = findMilestone(orgId, id);
  if (milestone.projectId "'!== projectId) return requireFound(null, "Milestone", id);
  if (milestone.closedAt !== null) throw new MilestoneStateError("closed");
  return milestone;
}

async function projectFor(actor: Actor, orgId: OrgId, projectId: ProjectId, write: boolean) {
  const project = requireFound(await projectRepo.findProjectById(orgId, projectId), "Project", projectId);
  assertCan(actor, write ? "project:update" : "project:read", projectResource(project));
  if (write) assertNotArchived("Project", project.id, project);
  return project;
}

function projectMilestones(orgId: OrgId, projectId: ProjectId): Milestone[] {
  return getDb().select().from(milestones).where(and(eq(milestones.orgId, orgId), eq(milestones.projectId, projectId))).all().map(mapMilestone);
}
function assertNameAvailable(orgId: OrgId, projectId: ProjectId, name: string, exclude?: MilestoneId) {
  const normalized = name.trim().toLowerCase();
  if (projectMilestones(orgId, projectId).some((m) => m.id !== exclude && m.name.trim().toLowerCase() === normalized)) throw new MilestoneStateError("name_taken");
}
function assertCapacity(orgId: OrgId, projectId: ProjectId) {
  if (projectMilestones(orgId, projectId).filter((m) => m.closedAt === null).length >= MAX_OPEN_MILESTONES_PER_PROJECT) throw new MilestoneStateError("too_many_open");
}

export async function createMilestone(actor: Actor, input: CreateMilestoneInput): Promise<Milestone> {
  assertOrgScope(actor, input.orgId);
  await projectFor(actor, input.orgId, input.projectId, true);
  const stamp = toIsoTimestamp(new Date());
  const milestone = getDb().transaction((tx) => {
    assertNameAvailable(input.orgId, input.projectId, input.name);
    assertCapacity(input.orgId, input.projectId);
    return mapMilestone(tx.insert(milestones).values({ id: newId(), orgId: input.orgId, projectId: input.projectId, name: input.name, targetDate: input.targetDate ?? null, closedAt: null, createdAt: stamp, updatedAt: stamp }).returning().get());
  });
  await emit("milestone.created", { ...actorEnvelope(actor), milestoneId: milestone.id, projectId: milestone.projectId });
  return milestone;
}

export async function updateMilestone(actor: Actor, input: UpdateMilestoneInput): Promise<Milestone> {
  assertOrgScope(actor, input.orgId);
  const before = findMilestone(input.orgId, input.milestoneId);
  await projectFor(actor, input.orgId, before.projectId, true);
  return getDb().transaction((tx) => {
    if (input.name !== undefined) assertNameAvailable(input.orgId, before.projectId, input.name, before.id);
    return mapMilestone(tx.update(milestones).set({ ...(input.name === undefined ? {} : { name: input.name }), ...(input.targetDate === undefined ? {} : { targetDate: input.targetDate }), updatedAt: toIsoTimestamp(new Date()) }).where(and(eq(milestones.orgId, input.orgId), eq(milestones.id, input.milestoneId))).returning().get());
  });
}

export async function closeMilestone(actor: Actor, input: CloseMilestoneInput): Promise<{ milestone: Milestone; movedIssueIds: readonly IssueId[] }> {
  assertOrgScope(actor, input.orgId);
  const before = findMilestone(input.orgId, input.milestoneId);
  await projectFor(actor, input.orgId, before.projectId, true);
  const result = getDb().transaction((tx) => {
    const current = findMilestone(input.orgId, input.milestoneId);
    if (current.closedAt !== null) throw new MilestoneStateError("closed");
    const target = input.moveOpenIssuesTo ?? null;
    if (target !== null) {
      if (target === current.id) requireFound(null, "Milestone", target);
      requireOpenProjectMilestone(input.orgId, current.projectId, target);
    }
    const stamp = toIsoTimestamp(new Date());
    const moved = tx.update(issues).set({ milestoneId: target, updatedAt: stamp }).where(and(eq(issues.orgId, input.orgId), eq(issues.projectId, current.projectId), eq(issues.milestoneId, current.id), isNull(issues.archivedAt), notInArray(issues.status, ["done", "canceled"]))).returning({ id: issues.id }).all();
    const milestone = mapMilestone(tx.update(milestones).set({ closedAt: stamp, updatedAt: stamp }).where(and(eq(milestones.orgId, input.orgId), eq(milestones.id, current.id))).returning().get());
    return { milestone, movedIssueIds: moved.map((row) => row.id as IssueId) };
  });
  await emit("milestone.closed", { ...actorEnvelope(actor), milestoneId: result.milestone.id, projectId: result.milestone.projectId, movedToMilestoneId: input.moveOpenIssuesTo ?? null, movedIssueIds: result.movedIssueIds });
  return result;
}

export async function reopenMilestone(actor: Actor, orgId: OrgId, milestoneId: MilestoneId): Promise<Milestone> {
  assertOrgScope(actor, orgId);
  const before = findMilestone(orgId, milestoneId);
  await projectFor(actor, orgId, before.projectId, true);
  const milestone = getDb().transaction((tx) => {
    const current = findMilestone(orgId, milestoneId);
    if (current.closedAt === null) throw new MilestoneStateError("already_open");
    assertCapacity(orgId, current.projectId);
    return mapMilestone(tx.update(milestones).set({ closedAt: null, updatedAt: toIsoTimestamp(new Date()) }).where(and(eq(milestones.orgId, orgId), eq(milestones.id, milestoneId))).returning().get());
  });
  await emit("milestone.reopened", { ...actorEnvelope(actor), milestoneId, projectId: milestone.projectId });
  return milestone;
}

function withProgress(milestone: Milestone, now: number): MilestoneWithProgress {
  const rows = getDb().select({ status: issues.status }).from(issues).where(and(eq(issues.orgId, milestone.orgId), eq(issues.projectId, milestone.projectId), eq(issues.milestoneId, milestone.id), isNull(issues.archivedAt))).all();
  const closed = rows.filter((row) => row.status === "done" || row.status === "canceled").length;
  const progress = { total: rows.length, open: rows.length - closed, closed };
  return { milestone, progress, overdue: milestone.closedAt === null && milestone.targetDate !== null && new Date(milestone.targetDate).getTime() < now && progress.open > 0 };
}
export async function listMilestones(actor: Actor, orgId: OrgId, projectId: ProjectId): Promise<readonly MilestoneWithProgress[]> {
  const now = Date.now();
  assertOrgScope(actor, orgId);
  await projectFor(actor, orgId, projectId, false);
  return projectMilestones(orgId, projectId).sort((a, b) => Number(a.closedAt !== null) - Number(b.closedAt !== null) || (a.targetDate === null ? (b.targetDate === null ? 0 : 1) : b.targetDate === null ? -1 : new Date(a.targetDate).getTime() - new Date(b.targetDate).getTime()) || a.createdAt.localeCompare(b.createdAt)).map((m) => withProgress(m, now));
}
export async function getMilestone(actor: Actor, orgId: OrgId, milestoneId: MilestoneId): Promise<MilestoneWithProgress> {
  const now = Date.now();
  assertOrgScope(actor, orgId);
  const milestone = findMilestone(orgId, milestoneId);
  await projectFor(actor, orgId, milestone.projectId, false);
  return withProgress(milestone, now);
}
