import { afterAll, beforeAll, describe, expect, it } from \"vitest\";
import { subscribe } from \"@/lib/event-bus\";
import { MilestoneStateError } from \"@/lib/milestones\";
import { toIsoTimestamp } from \"@/types/common\";
import { registerActivityListeners } from \"@/server/services/activity-service\";
import { listNotifications } from \"@/server/services/notification-service\";
import * as issueService from \"@/server/services/issue-service\";
import * as milestoneService from \"@/server/services/milestone-service\";
import { createTenant, issueInput, useTemporaryDatabase } from \"../server/_support/fixtures\";
import type { Tenant } from \"../server/_support/fixtures\";

let tenant: Tenant;
let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); tenant = await createTenant(\"milestone\"); });
afterAll(() => cleanup());

describe(\"milestones\", () => {
  it(\"moves only open live issues on close, records the event and applies alert preferences\", async () => {
    const actor = tenant.actors.owner;
    const orgId = tenant.org.id;
    const projectId = tenant.project.id;
    const detach = registerActivityListeners();
    const events: unknown[] = [];
    const off = subscribe(\"milestone.closed\", (event) => { events.push(event); });
    try {
      const milestone = await milestoneService.createMilestone(actor, { orgId, projectId, name: \"Release\", targetDate: toIsoTimestamp(\"2000-01-01\") });
      const target = await milestoneService.createMilestone(actor, { orgId, projectId, name: \"Next\", targetDate: null });
      const create = (title: string, assigneeId = tenant.userIds.member) => issueService.createIssue(actor, { ...issueInput(orgId, projectId, { title, assigneeId }), milestoneId: milestone.id });
      const open = await create(\"Open issue\");
      const done = await create(\"Closed issue\");
      const archived = await create(\"Archived issue\");
      await issueService.changeIssueStatus(actor, { orgId, issueId: done.id, status: \"done\" });
      await issueService.archiveIssue(actor, orgId, archived.id);
      expect(await milestoneService.getMilestone(actor, orgId, milestone.id)).toMatchObject({ progress: { total: 2, open: 1, closed: 1 }, overdue: true });
      await expect(milestoneService.closeMilestone(actor, { orgId, milestoneId: milestone.id, moveOpenIssuesTo: milestone.id })).rejects.toMatchObject({ code: \"not_found\" });
      expect(events).toHaveLength(0);
      const result = await milestoneService.closeMilestone(actor, { orgId, milestoneId: milestone.id, moveOpenIssuesTo: target.id });
      expect(result.movedIssueIds).toEqual([open.id]);
      expect(events).toHaveLength(1);
      expect((await issueService.getIssue(actor, orgId, done.id)).issue.milestoneId).toBe(milestone.id);
      expect((await issueService.getIssue(actor, orgId, archived.id)).issue.milestoneId).toBe(milestone.id);
      expect((await issueService.getIssue(actor, orgId, open.id)).issue.milestoneId).toBe(target.id);
      const notifications = await listNotifications(actor, { orgId, recipientId: tenant.userIds.member, unreadOnly: false, kind: [\"issue_milestone_changed\"], limit: 25, cursor: null });
      expect(notifications.items).toHaveLength(1);
      await expect(milestoneService.closeMilestone(actor, { orgId, milestoneId: milestone.id, moveOpenIssuesTo: null })).rejects.toMatchObject({ reason: \"closed\" });
      await milestoneService.reopenMilestone(actor, orgId, milestone.id);
    } finally { detach(); off(); }
  });

  it(\"enforces names and the open cap, including reopening\", async () => {
    const actor = tenant.actors.admin;
    const orgId = tenant.org.id;
    const projectId = tenant.project.id;
    await expect(milestoneService.createMilestone(actor, { orgId, projectId, name: \"  RELEASE  \", targetDate: null })).rejects.toMatchObject({ reason: \"name_taken\" });
    const all = await milestoneService.listMilestones(actor, orgId, projectId);
    for (let i = all.length; i < 10; i++) await milestoneService.createMilestone(actor, { orgId, projectId, name: "'`Extra ${i}`, targetDate: null });
    await expect(milestoneService.createMilestone(actor, { orgId, projectId, name: "Too many", targetDate: null })).rejects.toBeInstanceOf(MilestoneStateError);
    const first = all[0]!.milestone;
    await milestoneService.closeMilestone(actor, { orgId, milestoneId: first.id, moveOpenIssuesTo: null });
    await milestoneService.createMilestone(actor, { orgId, projectId, name: "Replacement", targetDate: null });
    await expect(milestoneService.reopenMilestone(actor, orgId, first.id)).rejects.toMatchObject({ reason: "too_many_open" });
  });
});
EOF
